variants.code_sketch:
BlockingQueue<Event> events = new ArrayBlockingQueue<>(256);

events.put(new PlaySound(SoundId.BLOOP, 0.8f));   // returns once enqueued

// owning thread, one item per tick:
Event e = events.poll();
if (e != null) handle(e);                          // or take() to block instead

ArrayDeque<Event> pending = new ArrayDeque<>();

pending.addLast(new PlaySound(SoundId.BLOOP, 0.8f));

// once per tick, on the same thread:
for (Event e; (e = pending.pollFirst()) != null; ) {
    handle(e);
}
